async function refreshData(){try{[S.health,S.data,S.evaluation,S.system]=await Promise.all([req('/v1/healthz'),req('/v1/dashboard'),req('/v1/evaluation'),req('/v1/system')]);$('#serverStatus').textContent='Local storage ready';$('#serverPulse').className='pulse ok';$('#merchantCount').textContent=S.data.counts.merchant;$('#conversationCount').textContent=S.data.conversations.length;return true}catch(e){S.data=null;$('#serverStatus').textContent='Local data unavailable';$('#serverPulse').className='pulse bad';return false}}
function toast(msg,kind='ok'){const t=$('#toast');t.textContent=msg;t.className=`toast show ${kind}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='toast',2600)}
function metric(label,value,icon,foot='From loaded challenge contexts'){return `<article class="card metric"><span class="metric-icon">${icon}</span><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="foot">${esc(foot)}</div></article>`}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">VERA AI · MERCHANT INTELLIGENCE</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function initials(s){return String(s||'V').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function merchantRows(){return entries('merchant').map(([id,m])=>{const i=identity(m),p=m.performance||{},t=entries('trigger').find(([,x])=>x.merchant_id===id)?.[1];return {id,m,i,p,t}})}
function rowsTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`}
function empty(title,detail,button=''){return `<div class="empty"><div><strong>${title}</strong><small>${detail}</small>${button?`<div style="margin-top:12px">${button}</div>`:''}</div></div>`}
function dashboard(){const d=S.data||{counts:{},contexts:{},conversations:[]};const merchants=merchantRows(),triggers=entries('trigger'),customers=entries('customer'),cats=entries('category'),convos=d.conversations||[];const byTrigger={};triggers.forEach(([,t])=>byTrigger[t.kind]=(byTrigger[t.kind]||0)+1);const pairs=Object.entries(byTrigger).sort((a,b)=>b[1]-a[1]).slice(0,7),max=Math.max(1,...pairs.map(x=>x[1]));return `${head('Good morning, Vera is ready','A live view of your local dataset and conversations saved in this browser.',`<button class="btn" data-page="contexts">Explore contexts</button><button class="btn primary" data-page="composer">✳ &nbsp;Compose a message</button>`)}<div class="tag cyan" style="margin-bottom:12px">● &nbsp;Local workspace · edits and conversations persist in browser storage</div><div class="grid metrics">${metric('Categories',d.counts.category||0,'◈')}${metric('Merchants',d.counts.merchant||0,'♙')}${metric('Customers',d.counts.customer||0,'♧')}${metric('Trigger events',d.counts.trigger||0,'⌁')}</div><div class="grid columns"><section class="card section-card"><div class="section-title"><div><h2>Trigger landscape</h2><p>Distribution across locally stored trigger contexts</p></div><span class="tag">${triggers.length} loaded</span></div><div class="legend"><span><i></i>Trigger contexts</span></div><div class="chart"><div class="chart-y"><span>${max}</span><span>${Math.ceil(max*.75)}</span><span>${Math.ceil(max*.5)}</span><span>0</span></div><div class="chart-main"><div class="chart-grid"><i></i><i></i><i></i><i></i></div><div class="chart-bars">${pairs.map(([k,v])=>`<div class="chart-bar" style="--h:${Math.max(8,v/max*100)}%" title="${esc(k)}: ${v}"></div>`).join('')}</div><div class="chart-x">${pairs.map(([k])=>`<span>${esc(titleCase(k).slice(0,14))}</span>`).join('')}</div></div></div></section><section class="card section-card"><div class="section-title"><div><h2>Recent conversations</h2><p>Saved in this browser’s localStorage</p></div><button class="table-action" data-page="conversations">View all →</button></div>${convos.length?`<div class="list">${convos.slice(-5).reverse().map(conversationRow).join('')}</div>`:empty('No conversations yet','Start a test conversation from the composer or trigger center.',`<button class="btn primary" data-page="triggers">Explore triggers</button>`)}</section></div><div class="grid columns equal" style="margin-top:13px"><section class="card section-card"><div class="section-title"><div><h2>Merchant network</h2><p>Profiles loaded from the bundled local dataset</p></div><button class="table-action" data-page="merchants">Browse merchants →</button></div><div class="list">${merchants.slice(0,5).map(({id,i,p,m})=>`<div class="list-row"><span class="avatar">${initials(i.name)}</span><div class="grow"><strong>${esc(i.name||id)}</strong><small>${esc(i.locality||i.city||'Location unavailable')} · ${esc(titleCase(m.category_slug))}</small></div><span class="right">CTR ${pct(p.ctr)}</span></div>`).join('')}</div></section><section class="card section-card"><div class="section-title"><div><h2>Category voice profiles</h2><p>Category rules used by the local composer</p></div><button class="table-action" data-page="contexts">View contexts →</button></div><div class="list">${cats.map(([id,c])=>`<div class="list-row"><span class="avatar cyan">${initials(c.display_name)}</span><div class="grow"><strong>${esc(c.display_name||id)}</strong><small>${esc(c.voice?.tone||'Voice profile')}</small></div><span class="tag gray">${(c.voice?.vocab_taboo||c.voice?.taboos||[]).length} taboos</span></div>`).join('')}</div></section></div><footer class="page-foot">Vera AI Challenge · Local deterministic composer · no API or database required.</footer>`}
function conversationRow(c){const m=S.data?.contexts?.merchant?.[c.merchant_id]||{};return `<div class="list-row" data-open-conversation="${esc(c.conversation_id)}"><span class="avatar violet">${initials(identity(m).name)}</span><div class="grow"><strong>${esc(identity(m).name||c.merchant_id||'Unknown merchant')}</strong><small>${esc(titleCase(c.strategy))} · ${c.messages?.length||0} messages</small></div><span class="tag ${c.status==='open'?'green':'gray'}">${esc(c.status)}</span></div>`}
function merchantsPage(){const data=merchantRows();return `${head('Merchants','Explore the 50 supplied merchant profiles and their business context.',`<span class="tag">${data.length} profiles</span>`)}<div class="toolbar"><input id="searchMerchant" class="search" placeholder="Search merchant, city, or locality…" aria-label="Search merchants"><select class="select" id="merchantCategory"><option value="">All categories</option>${entries('category').map(([id,c])=>`<option value="${id}">${esc(c.display_name||id)}</option>`).join('')}</select><select class="select" id="merchantStatus"><option value="">All subscription states</option>${['active','expired','trial'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="merchantTable"></div>`}
function paintMerchantRows(){const search=($('#searchMerchant')?.value||'').toLowerCase(),cat=$('#merchantCategory')?.value||'',status=$('#merchantStatus')?.value||'';const found=merchantRows().filter(({id,i,m})=>(`${i.name} ${i.city} ${i.locality} ${id}`.toLowerCase().includes(search))&&(!cat||m.category_slug===cat)&&(!status||m.subscription?.status===status));const body=found.map(({id,i,p,m,t})=>`<tr><td><button class="merchant-cell table-action" data-open-merchant="${esc(id)}"><span class="avatar">${initials(i.name)}</span><span><b>${esc(i.name||id)}</b><small>${esc(i.locality||'')} · ${esc(i.city||'')}</small></span></button></td><td>${esc(S.data.contexts.category[m.category_slug]?.display_name||titleCase(m.category_slug))}</td><td>${m.rating??'—'}</td><td>${m.review_count??m.reviews??'—'}</td><td>${pct(p.ctr)}</td><td>${p.views??'—'}</td><td>${p.calls??'—'}</td><td><span class="tag ${m.subscription?.status==='active'?'green':'gray'}">${esc(m.subscription?.status||'unknown')}</span></td><td>${esc(t?titleCase(t.kind):'—')}</td></tr>`).join('');$('#merchantTable').innerHTML=found.length?rowsTable(['MERCHANT','CATEGORY','RATING','REVIEWS','CTR','VIEWS','CALLS','PLAN','CURRENT TRIGGER'],body):empty('No matching merchants','Try a different search or filter.')}
function merchantDetail(id){const m=S.data.contexts.merchant[id];if(!m)return;S.selectedMerchant=id;const i=identity(m),p=m.performance||{},cat=S.data.contexts.category[m.category_slug]||{},active=(m.offers||[]).filter(o=>o.status==='active'),tr=entries('trigger').filter(([,t])=>t.merchant_id===id);return `${head(`<span class="back" data-page="merchants">← Merchants</span>${esc(i.name||id)}`,`${esc(i.locality||'')} · ${esc(i.city||'')} · ${esc(cat.display_name||m.category_slug)}`,`<button class="btn primary" data-compose-merchant="${esc(id)}">✳ Compose</button>`)}<div class="grid metrics">${metric('Views · 30 days',p.views??'—','◫')}${metric('Calls · 30 days',p.calls??'—','⌕')}${metric('Directions · 30 days',p.directions??'—','↗')}${metric('Click-through rate',pct(p.ctr),'◎',cat.peer_stats?.avg_ctr!=null?`Category peer CTR ${pct(cat.peer_stats.avg_ctr)}`:'Peer CTR unavailable')}</div><div class="grid columns"><section class="card section-card"><div class="section-title"><div><h2>Merchant profile</h2><p>Identity and subscription details</p></div></div>${Object.entries({'Business':i.name,'Owner':i.owner_first_name,'Locality':i.locality,'City':i.city,'Languages':(i.languages||[]).join(', '),'Verified':i.verified==null?'—':i.verified?'Yes':'No','Subscription':m.subscription?.status,'Plan':m.subscription?.plan,'Days remaining':m.subscription?.days_remaining}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}</section><section class="card section-card"><div class="section-title"><div><h2>Offers & signals</h2><p>Only values found in this merchant context</p></div></div><div class="list">${active.length?active.map(x=>`<div class="list-row"><span class="avatar green">＋</span><div class="grow"><strong>${esc(x.title)}</strong><small>Active merchant offer</small></div><span class="tag green">Active</span></div>`).join(''):empty('No active offers','No active merchant offer is present in this context.')}${(m.signals||[]).map(x=>`<div class="list-row"><span class="avatar orange">!</span><div class="grow"><strong>${esc(titleCase(x))}</strong><small>Merchant signal</small></div></div>`).join('')}</div></section></div><div class="grid columns equal" style="margin-top:13px"><section class="card section-card"><div class="section-title"><div><h2>Customer aggregate</h2><p>Aggregate data only</p></div></div><pre class="json-view">${esc(JSON.stringify(m.customer_aggregate||{},null,2))}</pre></section><section class="card section-card"><div class="section-title"><div><h2>Active triggers</h2><p>Context-trigger links for this merchant</p></div></div>${tr.length?`<div class="list">${tr.map(([tid,t])=>`<div class="list-row" data-open-trigger="${esc(tid)}"><span class="avatar cyan">⌁</span><div class="grow"><strong>${esc(titleCase(t.kind))}</strong><small>${esc(tid)} · urgency ${t.urgency??'—'}</small></div><span class="tag ${t.scope==='customer'?'cyan':'blue'}">${esc(t.scope)}</span></div>`).join('')}</div>`:empty('No trigger linked','The supplied triggers do not reference this merchant.')}</section></div>`}
function customersPage(){return `${head('Customers','Consent-aware customer contexts. Contact details are masked in this challenge dataset.',`<span class="tag">${entries('customer').length} profiles</span>`)}<div class="toolbar"><input class="search" id="searchCustomer" placeholder="Search by customer or merchant…" aria-label="Search customers"><select class="select" id="customerState"><option value="">All states</option>${['active','new','lapsed_soft','lapsed_hard','churned'].map(x=>`<option value="${x}">${titleCase(x)}</option>`).join('')}</select><select class="select" id="customerLanguage"><option value="">All languages</option><option value="hi">Hindi / Hinglish</option><option value="en">English</option></select></div><div id="customerTable"></div>`}
function paintCustomers(){const q=($('#searchCustomer')?.value||'').toLowerCase(),state=$('#customerState')?.value||'',lang=$('#customerLanguage')?.value||'';const items=entries('customer').filter(([id,c])=>{const mi=S.data.contexts.merchant[c.merchant_id]||{},needle=`${id} ${identity(c).name||''} ${identity(mi).name||''}`.toLowerCase();return needle.includes(q)&&(!state||c.state===state)&&(!lang||String(identity(c).language_pref||'').toLowerCase().includes(lang))});$('#customerTable').innerHTML=items.length?rowsTable(['CUSTOMER','MERCHANT','STATE','LAST VISIT','VISITS','SERVICES','LANGUAGE','CONSENT'],items.map(([id,c])=>{const m=S.data.contexts.merchant[c.merchant_id]||{},co=c.consent?.scope||[];return `<tr><td><button class="table-action" data-open-customer="${esc(id)}"><b>${esc(identity(c).name||id)}</b><small>${esc(identity(c).age_band||'')}</small></button></td><td>${esc(identity(m).name||c.merchant_id)}</td><td><span class="tag ${c.state?.includes('lapsed')?'amber':'green'}">${esc(titleCase(c.state))}</span></td><td>${esc(c.relationship?.last_visit||'—')}</td><td>${c.relationship?.visits_total??'—'}</td><td>${esc((c.relationship?.services_received||[]).slice(0,2).join(', ')||'—')}</td><td>${esc(identity(c).language_pref||'—')}</td><td>${esc(co.map(titleCase).join(', ')||'Not supplied')}</td></tr>`}).join('')):empty('No matching customer profiles','Change the filters to see more challenge contexts.')}
function customerDetail(id){const c=S.data.contexts.customer[id];if(!c)return;S.selectedCustomer=id;const m=S.data.contexts.merchant[c.merchant_id]||{};return `${head(`<span class="back" data-page="customers">← Customers</span>${esc(identity(c).name||id)}`,`Customer context · ${esc(identity(m).name||c.merchant_id)}`,`<button class="btn" data-page="contexts">View raw context</button>`)}<div class="grid columns equal"><section class="card section-card"><h2>Relationship</h2>${Object.entries({'State':titleCase(c.state),'First visit':c.relationship?.first_visit,'Last visit':c.relationship?.last_visit,'Total visits':c.relationship?.visits_total,'Services':(c.relationship?.services_received||[]).join(', '),'Language':identity(c).language_pref,'Preferred time':c.preferences?.preferred_slots,'WhatsApp opted in':c.preferences?.reminder_opt_in?'Yes':'No'}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}</section><section class="card section-card"><h2>Consent & privacy</h2><div class="tag ${c.consent?.scope?.length?'green':'red'}">${c.consent?.scope?.length?'Consent scopes supplied':'No consent scope supplied'}</div><div class="list" style="margin-top:12px">${(c.consent?.scope||[]).map(x=>`<div class="list-row"><span class="avatar green">✓</span><div class="grow"><strong>${esc(titleCase(x))}</strong><small>Consent scope from context</small></div></div>`).join('')||empty('No consent scope','Customer sends will be suppressed without the required consent.')}</div><p class="note">Phone identifiers remain redacted; this UI does not initiate real outreach.</p></section></div>`}
function triggersPage(){return `${head('Trigger center','Browse event contexts, urgency, expiry, suppression and affected profiles.',`<span class="tag">${entries('trigger').length} contexts</span>`)}<div class="toolbar"><input class="search" id="searchTrigger" placeholder="Search trigger or merchant…"><select class="select" id="triggerScope"><option value="">All scopes</option><option>merchant</option><option>customer</option></select><select class="select" id="triggerSource"><option value="">All sources</option><option>internal</option><option>external</option></select><select class="select" id="triggerUrgency"><option value="">All urgency</option><option value="4">Urgency 4+</option><option value="3">Urgency 3+</option></select></div><div id="triggerTable"></div>`}
function paintTriggers(){const q=($('#searchTrigger')?.value||'').toLowerCase(),scope=$('#triggerScope')?.value||'',src=$('#triggerSource')?.value||'',urg=Number($('#triggerUrgency')?.value||0),items=entries('trigger').filter(([id,t])=>`${id} ${t.kind} ${t.merchant_id}`.toLowerCase().includes(q)&&(!scope||t.scope===scope)&&(!src||t.source===src)&&(!urg||Number(t.urgency)>=urg));$('#triggerTable').innerHTML=items.length?rowsTable(['TRIGGER','TYPE','SCOPE','SOURCE','URGENCY','MERCHANT','EXPIRES','SUPPRESSION',''],items.map(([id,t])=>`<tr><td><b>${esc(id)}</b></td><td>${esc(titleCase(t.kind))}</td><td><span class="tag ${t.scope==='customer'?'cyan':'blue'}">${esc(t.scope)}</span></td><td><span class="tag ${t.source==='external'?'amber':'gray'}">${esc(t.source)}</span></td><td><span class="tag ${Number(t.urgency)>=4?'red':'gray'}">${esc(t.urgency??'—')}</span></td><td>${esc(identity(S.data.contexts.merchant[t.merchant_id]).name||t.merchant_id||'—')}</td><td>${esc(t.expires_at||'—')}</td><td>${esc(t.suppression_key||'—')}</td><td><button class="table-action" data-open-trigger="${esc(id)}">Details</button></td></tr>`).join('')):empty('No matching triggers','Try a different filter.')}
function triggerDetail(id){const t=S.data.contexts.trigger[id];if(!t)return;S.selectedTrigger=id;const m=S.data.contexts.merchant[t.merchant_id]||{},cat=S.data.contexts.category[m.category_slug]||{};return `${head(`<span class="back" data-page="triggers">← Trigger center</span>${esc(titleCase(t.kind))}`,`${esc(t.id||id)} · ${esc(t.scope)} scope`, `<button class="btn primary" data-run-trigger="${esc(id)}">Run simulated tick</button>`)}<div class="grid columns"><section class="card section-card"><h2>Trigger details</h2>${Object.entries({'Source':titleCase(t.source),'Urgency':t.urgency,'Merchant':identity(m).name,'Locality':identity(m).locality,'Customer':t.customer_id,'Expires':t.expires_at,'Suppression key':t.suppression_key,'AI strategy':titleCase(window.routeTrigger?.(t)||t.kind)}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}</section><section class="card section-card"><h2>Payload</h2><pre class="json-view">${esc(JSON.stringify(t.payload||{},null,2))}</pre></section></div>`}
function composerPage(){const ms=merchantRows(),ts=entries('trigger'),cs=entries('customer'),firstM=ms[0]?.id||'',firstT=ts[0]?.[0]||'',firstC=cs[0]?.[0]||'';return `${head('AI message composer','Generate a context-grounded draft, inspect the strategy, then start a simulated conversation.',`<span class="tag cyan">composer_v1</span>`)}<div class="composer-layout"><section class="card panel"><h2>Four-context selection</h2><label class="form-label" for="composeMerchant">MERCHANT</label><select class="form-control" id="composeMerchant">${ms.map(({id,i})=>`<option value="${esc(id)}">${esc(i.name||id)} · ${esc(i.locality||i.city||'')}</option>`).join('')}</select><label class="form-label" for="composeTrigger">TRIGGER</label><select class="form-control" id="composeTrigger">${ts.map(([id,t])=>`<option value="${esc(id)}">${esc(titleCase(t.kind))} · ${esc(t.scope)}</option>`).join('')}</select><label class="form-label" for="composeCustomer">CUSTOMER · OPTIONAL</label><select class="form-control" id="composeCustomer"><option value="">None · merchant-facing</option>${cs.map(([id,c])=>`<option value="${esc(id)}">${esc(identity(c).name||id)} · ${esc(c.state||'')}</option>`).join('')}</select><div id="contextPreview" style="margin-top:14px"></div><div class="strategy-list" id="strategy"></div><button class="btn primary" id="generate" style="width:100%;margin-top:10px">✳ &nbsp;Generate & validate</button></section><section class="card panel"><div class="section-title"><div><h2>Vera preview</h2><p>Draft generated from selected dataset contexts</p></div><span class="tag cyan">AI DRAFT</span></div><div class="message-preview"><div class="preview-label">WHATSAPP · SIMULATION ONLY</div><div id="messagePreview" class="empty"><div><strong>Select context, then generate</strong><small>No message is sent to a real merchant or customer.</small></div></div><div class="preview-meta" id="messageMeta"></div></div><div style="display:flex;gap:7px;margin-top:10px"><button class="btn" id="copyMessage" disabled>Copy draft</button><button class="btn" id="runConversation" disabled>Start simulated conversation →</button></div></section><section class="card panel pipeline-card"><h2>Validation pipeline</h2><ul class="check-pipeline" id="pipeline">${['Context loaded','Trigger resolved','Language detected','Strategy selected','Message generated','Fact validation','CTA validation'].map(x=>`<li class="pending"><span>○</span>${x}</li>`).join('')}</ul><div id="validationSummary" class="note">Waiting for a composer request.</div></section></div>`}
function syncComposer(){const mid=$('#composeMerchant')?.value,tid=$('#composeTrigger')?.value,cid=$('#composeCustomer')?.value,m=S.data.contexts.merchant[mid]||{},t=S.data.contexts.trigger[tid]||{},i=identity(m),c=cid?S.data.contexts.customer[cid]:null,p=m.performance||{},cat=S.data.contexts.category[m.category_slug]||{},active=(m.offers||[]).find(x=>x.status==='active');$('#contextPreview').innerHTML=`<div class="context-chip"><span>Category voice</span><b>${esc(cat.voice?.tone||'—')}</b></div><div class="context-chip"><span>CTR · ${p.window_days||30}d</span><b>${pct(p.ctr)}</b></div><div class="context-chip"><span>Peer CTR</span><b>${pct(cat.peer_stats?.avg_ctr)}</b></div><div class="context-chip"><span>Active offer</span><b>${esc(active?.title||'None supplied')}</b></div><div class="context-chip"><span>Trigger</span><b>${esc(titleCase(t.kind))}</b></div>${c?`<div class="context-chip"><span>Customer consent</span><b>${esc((c.consent?.scope||[]).join(', ')||'Not supplied')}</b></div>`:''}`;$('#strategy').innerHTML=`<span class="tag blue">${esc(titleCase(window.routeTrigger?.(t)||t.kind||'Context strategy'))}</span><span class="tag cyan">${c?'Customer convenience':'Specificity'}</span><span class="tag">${esc(i.locality||i.city||'Local relevance')}</span>`;S.compose={mid,tid,cid};$('#messagePreview').innerHTML=`<div class="empty"><div><strong>${esc(i.name||mid||'Select a merchant')}</strong><small>${esc(titleCase(t.kind||''))} · ${esc(c?identity(c).name:'Merchant-facing')}</small></div></div>`;$('#messageMeta').innerHTML='';$('#copyMessage').disabled=true;$('#runConversation').disabled=true;S.compose.result=null}
function analyticsPage(){const trig=entries('trigger'),cats=entries('category'),convos=S.data.conversations||[],dist={};trig.forEach(([,t])=>dist[t.kind]=(dist[t.kind]||0)+1);const chart=Object.entries(dist).sort((a,b)=>b[1]-a[1]).slice(0,8),max=Math.max(1,...chart.map(x=>x[1]));return `${head('Analytics','Descriptive counts derived from loaded challenge contexts and this process’s actual conversations.',`<span class="tag">No fabricated engagement rates</span>`)}<div class="grid metrics">${metric('Triggers by context',trig.length,'⌁')}${metric('Categories represented',cats.length,'◈')}${metric('Conversations started',convos.length,'▤')}${metric('Current process turns',convos.reduce((a,c)=>a+(c.messages?.length||0),0),'↻')}</div><div class="grid columns"><section class="card section-card"><div class="section-title"><div><h2>Trigger kind distribution</h2><p>Counts of supplied trigger records</p></div></div><div class="list">${chart.map(([k,v])=>`<div class="list-row"><div class="grow"><strong>${esc(titleCase(k))}</strong><small>${v} supplied contexts</small><div style="height:4px;background:#14243a;margin-top:6px;border-radius:4px"><div style="height:4px;width:${v/max*100}%;background:#438af0;border-radius:4px"></div></div></div><span class="right">${v}</span></div>`).join('')}</div></section><section class="card section-card"><div class="section-title"><div><h2>Conversation instrumentation</h2><p>localStorage activity counters</p></div></div>${Object.entries(S.data.metrics?.latency_ms||{}).map(([route,vals])=>`<div class="insight-item"><span>${esc(route)}</span><strong>${vals.length} req · avg ${(vals.reduce((a,b)=>a+b,0)/Math.max(1,vals.length)).toFixed(1)} ms</strong></div>`).join('')||empty('No API telemetry yet','Counters update as the local workspace is used.')}</section></div>`}
function evaluationPage(){const e=S.evaluation||{cases:[],valid:0,total:0};return `${head('Challenge evaluation','Local heuristic validation of the canonical 30-case submission. Not an official judge score.',`<span class="tag amber">LOCAL HEURISTIC · NOT OFFICIAL</span>`)}<div class="grid metrics">${metric('Canonical cases',e.total,'◉')}${metric('Valid outputs',e.valid,'✓')}${metric('Failed outputs',e.total-e.valid,'!')}${metric('Official AI score','Not measured','—','Judge credential not configured')}</div><div class="grid columns equal"><section class="card section-card"><div class="section-title"><div><h2>Challenge dimensions</h2><p>Evaluation rubric · no invented scores</p></div></div>${['Specificity','Category fit','Merchant fit','Trigger relevance','Engagement compulsion'].map((x,i)=>`<div class="insight-item"><span>${x}</span><strong><span class="tag cyan">Rubric ${i+1}/5</span></strong></div>`).join('')}</section><section class="card section-card"><div class="section-title"><div><h2>Engineering checks</h2><p>Results from local validator and JSONL</p></div></div>${[['Required fields','30/30 valid'],['Customer routing','Validated per case'],['JSONL schema','30 parseable rows'],['Official scoring','Unavailable without judge LLM credential']].map(([a,b])=>`<div class="insight-item"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('')}</section></div><div class="card section-card" style="margin-top:13px"><div class="section-title"><div><h2>Canonical test cases</h2><p>Open a draft to review exact generated copy.</p></div></div>${rowsTable(['CASE','MERCHANT','TRIGGER','CTA','ROUTE','VALIDATION','DRAFT'],(e.cases||[]).map(c=>`<tr><td><b>${esc(c.test_id)}</b></td><td>${esc(c.merchant||'—')}</td><td>${esc(titleCase(c.trigger||''))}</td><td>${esc(c.cta||'—')}</td><td>${esc(c.send_as||'—')}</td><td><span class="tag ${c.validation_errors?'red':'green'}">${c.validation_errors?'Warning':'Valid'}</span></td><td title="${esc(c.body)}">${esc((c.body||'').slice(0,100))}${(c.body||'').length>100?'…':''}</td></tr>`).join(''))}</div>`}
function apiPage(){const met=S.data.metrics||{};return `${head('Local activity','Request telemetry and simulated actions saved in this browser.',`<button class="btn" id="refreshApi">↻ Refresh status</button>`)}<div class="grid metrics">${metric('Total requests',met.requests||0,'⌘')}${metric('Successful',met.success||0,'✓')}${metric('Errors',met.errors||0,'!')}${metric('Contexts loaded',S.health?Object.values(S.health.contexts_loaded).reduce((a,b)=>a+b,0):0,'▧')}</div><div class="card section-card">${rowsTable(['LOCAL ACTION','STATUS','REQUESTS','SUCCESS','ERRORS','AVG LATENCY'],['/v1/context','/v1/tick','/v1/reply','/v1/healthz','/v1/metadata','/v1/compose','/v1/dashboard'].map(path=>{const n=met.latency_ms?.[path]||[],avg=n.length?(n.reduce((a,b)=>a+b,0)/n.length).toFixed(1)+' ms':'No telemetry';return `<tr><td><b>${path}</b></td><td><span class="tag ${S.health?'green':'red'}">${S.health?'Online':'Offline'}</span></td><td>${n.length}</td><td>${n.length?'Recorded':'—'}</td><td>See global API errors</td><td>${avg}</td></tr>`}).join(''))}</div><p class="note">This preview runs its actions in your browser. Conversation data and activity counters are saved in localStorage.</p>`}
function contextsPage(){return `${head('Context store','Inspect category, merchant, customer and trigger payloads saved in this browser.',`<span class="tag">${S.health?Object.values(S.health.contexts_loaded).reduce((a,b)=>a+b,0):0} loaded</span>`)}<div class="tabs">${['category','merchant','customer','trigger'].map(x=>`<button class="pill-filter ${S.scope===x?'active':''}" data-scope="${x}">${titleCase(x)} <b>${S.health?.contexts_loaded?.[x]||0}</b></button>`).join('')}</div><div class="grid columns" style="margin-top:12px"><section class="card section-card"><div class="toolbar"><input id="contextSearch" class="search" placeholder="Filter ${S.scope} IDs…"></div><div class="context-list" id="contextList"></div></section><section class="card section-card"><div class="section-title"><div><h2>Payload inspector</h2><p>Read-only view · no secrets shown</p></div><span class="tag">${esc(S.scope)}</span></div><div id="contextPayload">${empty('Select a context','Choose a row to inspect its version and source payload.')}</div></section></div>`}
function paintContexts(){const list=entries(S.scope).filter(([id,p])=>id.toLowerCase().includes(($('#contextSearch')?.value||'').toLowerCase()));$('#contextList').innerHTML=list.map(([id,p])=>{const record=S.data.contexts[S.scope][id];return `<button class="list-row context-row ${S.scopeId===id?'selected':''}" data-context-id="${esc(id)}"><span class="avatar">${initials(id)}</span><span class="grow"><strong>${esc(idOf(S.scope,id,p))}</strong><small>v${record?.version||1} · ${S.scope}</small></span><span class="tag gray">JSON</span></button>`}).join('')||empty('No contexts','This scope currently has no loaded payloads.');if(S.scopeId&&list.some(x=>x[0]===S.scopeId))showContext(S.scopeId)}
async function showContext(id){S.scopeId=id;const p=S.data.contexts[S.scope][id];let version=1;try{version=(await req(`/v1/context/${S.scope}/${encodeURIComponent(id)}`)).version}catch{}$('#contextPayload').innerHTML=`<div class="insight-item"><span>ID</span><strong>${esc(id)}</strong></div><div class="insight-item"><span>Version</span><strong>${version}</strong></div><div class="insight-item"><span>Scope</span><strong>${esc(S.scope)}</strong></div><pre class="json-view">${esc(JSON.stringify(p,null,2))}</pre>`;$$('.context-row').forEach(x=>x.classList.toggle('selected',x.dataset.contextId===id))}
function settingsPage(){return `${head('Local settings','Browser-local configuration and bundled dataset status.',`<span class="tag cyan">CHALLENGE MODE</span>`)}<div class="grid columns equal"><section class="card section-card"><h2>AI provider</h2>${Object.entries({'Provider':S.system?.provider,'Model':S.system?.model,'Temperature':S.system?.temperature,'LLM calls enabled':S.system?.llm_enabled?'Yes':'No · deterministic fallback','Composer':S.system?.composer_version,'Deterministic fallback':S.system?.feature_flags?.deterministic_fallback?'Enabled':'Disabled'}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}</section><section class="card section-card"><h2>Service & dataset</h2>${Object.entries({'Server':S.health?.status,'This tab active':`${S.health?.uptime_seconds||0}s`,'Dataset source':'local-data.json','Category contexts':S.health?.contexts_loaded?.category,'Merchant contexts':S.health?.contexts_loaded?.merchant,'Customer contexts':S.health?.contexts_loaded?.customer,'Trigger contexts':S.health?.contexts_loaded?.trigger}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}<p class="note">This browser-only mode does not use a provider or store credentials.</p></section></div>`}
function render(page=S.page){S.page=page;const names={overview:'Overview',conversations:'Conversations',merchants:'Merchants',customers:'Customers',triggers:'Trigger center',composer:'AI composer',analytics:'Analytics',evaluation:'Evaluation',api:'Local activity',contexts:'Context store',settings:'Settings'};$('#crumb').textContent=names[page]||names.overview;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const target=$('#page');if(!S.data){target.innerHTML=`${head('Local dataset unavailable','Restore local-data.json or clear this browser’s Vera storage to reload the bundled dataset.',`<button class="btn primary" id="retry">Retry connection</button>`)}<div class="card">${empty('No local data','The bundled dataset could not be read from this folder.')}</div>`;return}const view={overview:dashboard,conversations:conversationsPage,merchants:merchantsPage,customers:customersPage,triggers:triggersPage,composer:composerPage,analytics:analyticsPage,evaluation:evaluationPage,api:apiPage,contexts:contextsPage,settings:settingsPage}[page]||dashboard;target.innerHTML=view();if(page==='merchants')paintMerchantRows();if(page==='customers')paintCustomers();if(page==='triggers')paintTriggers();if(page==='contexts')paintContexts();if(page==='composer')syncComposer()}
function conversationsPage(){const cs=(S.data.conversations||[]).slice().reverse();return `${head('Conversations','Simulated conversations are stored in this browser. No real messages are sent.',`<span class="tag">${cs.length} in process</span>`)}${cs.length?`<div class="conversation-layout"><section class="card panel chat"><div class="chat-head"><span class="avatar cyan">V</span><div class="grow"><strong>${esc(S.selectedConversation||'Select a conversation')}</strong><small class="note">Local simulation · messages persisted in this browser</small></div><span class="tag green">${esc(cs.find(x=>x.conversation_id===S.selectedConversation)?.status||'open')}</span></div><div class="chat-log" id="chatLog">${S.selectedConversation?chatMessages(S.selectedConversation):empty('Choose a conversation','Select an item from the list below.')}</div><form id="replyForm" class="reply-form"><input class="form-control" id="replyText" placeholder="Simulate merchant reply…" aria-label="Simulated reply"><button class="btn primary">Send test reply</button></form></section><aside class="card panel"><h2>Conversation insights</h2><div id="conversationInsights">${S.selectedConversation?insights(S.selectedConversation):empty('No selection','Choose a conversation to inspect state.')}</div></aside></div><section class="card section-card" style="margin-top:13px"><div class="section-title"><div><h2>In-process conversations</h2><p>Click to inspect the conversation state.</p></div></div><div class="list">${cs.map(conversationRow).join('')}</div></section>`:empty('No active conversations','Start one from AI Composer or Trigger Center.','<button class="btn primary" data-page="composer">Open AI Composer</button>')}`}
function chatMessages(id){const c=(S.data.conversations||[]).find(x=>x.conversation_id===id);return c?(c.messages||[]).map(m=>`<div class="msg ${m.role==='vera'?'vera':''}">${esc(m.body)}<small>${esc(titleCase(m.role))} · ${when(m.at?new Date(m.at*1000).toISOString():null)}</small></div>`).join(''):empty('Conversation unavailable','The selected conversation may have ended.')}
function insights(id){const c=(S.data.conversations||[]).find(x=>x.conversation_id===id);if(!c)return '';const t=S.data.contexts.trigger[c.trigger_id]||{};return Object.entries({'Intent':titleCase(c.intent),'Language':c.language,'Trigger':t.kind,'Strategy':titleCase(c.strategy),'Auto reply':c.auto_reply_detected?'Detected':'No','Turn':c.turn_number,'CTA':c.last_cta,'Status':c.status,'Suppression':(c.suppression_keys||[]).length?'Passed':'—'}).map(([k,v])=>`<div class="insight-item"><span>${k}</span><strong>${esc(v??'—')}</strong></div>`).join('')}
function openConversation(id){S.selectedConversation=id;render('conversations')}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-page],[data-open-merchant],[data-open-customer],[data-open-trigger],[data-open-conversation],[data-context-id],[data-scope],[data-run-trigger],[data-compose-merchant]');if(!b)return;if(b.dataset.page){render(b.dataset.page);$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');return}if(b.dataset.openMerchant){const html=merchantDetail(b.dataset.openMerchant);S.page='merchantDetail';$('#page').innerHTML=html;$('#crumb').textContent='Merchant profile';return}if(b.dataset.openCustomer){const html=customerDetail(b.dataset.openCustomer);S.page='customerDetail';$('#page').innerHTML=html;$('#crumb').textContent='Customer profile';return}if(b.dataset.openTrigger){const html=triggerDetail(b.dataset.openTrigger);S.page='triggerDetail';$('#page').innerHTML=html;$('#crumb').textContent='Trigger details';return}if(b.dataset.openConversation){openConversation(b.dataset.openConversation);return}if(b.dataset.scope){S.scope=b.dataset.scope;S.scopeId=null;render('contexts');return}if(b.dataset.contextId){showContext(b.dataset.contextId);return}if(b.dataset.composeMerchant){render('composer');$('#composeMerchant').value=b.dataset.composeMerchant;syncComposer();return}if(b.dataset.runTrigger){b.disabled=true;try{const r=await req('/v1/tick',{method:'POST',body:JSON.stringify({now:'2026-04-26T12:00:00Z',available_triggers:[b.dataset.runTrigger]})});await refreshData();render('triggers');toast(r.actions.length?`Started ${r.actions.length} simulated conversation${r.actions.length===1?'':'s'}`:'No action: trigger suppressed, expired, or missing consent');}catch(err){toast(err.message,'error')}return}if(b.id==='generate'){await generate();return}if(b.id==='copyMessage'){if(S.compose?.result?.message?.body){await navigator.clipboard.writeText(S.compose.result.message.body);toast('Draft copied to clipboard')}return}if(b.id==='runConversation'){const tid=S.compose?.tid;if(!tid)return;try{const r=await req('/v1/tick',{method:'POST',body:JSON.stringify({now:'2026-04-26T12:00:00Z',available_triggers:[tid]})});await refreshData();if(r.actions.length){S.selectedConversation=r.actions[0].conversation_id;render('conversations');toast('Simulated conversation started')}else toast('No send: trigger is suppressed, expired, or consent is missing','error')}catch(err){toast(err.message,'error')}return}if(b.id==='retry'||b.id==='refresh'||b.id==='refreshApi'){await refreshData();render(S.page);toast(S.health?'Local workspace ready':'Local dataset unavailable',S.health?'ok':'error');return}if(b.id==='collapse'){document.body.classList.toggle('collapsed');return}if(b.id==='mobileMenu'){ $('#sidebar').classList.toggle('open');$('#scrim').classList.toggle('show');return}if(b.id==='theme'){document.body.classList.toggle('light');localStorage.setItem('vera-theme',document.body.classList.contains('light')?'light':'dark');return}if(b.id==='help'){toast('Challenge Demo · API docs are available in README.md');return}if(b.id==='sendReply'){return}});
document.addEventListener('input',e=>{if(['searchMerchant','merchantCategory','merchantStatus'].includes(e.target.id))paintMerchantRows();if(['searchCustomer','customerState','customerLanguage'].includes(e.target.id))paintCustomers();if(['searchTrigger','triggerScope','triggerSource','triggerUrgency'].includes(e.target.id))paintTriggers();if(e.target.id==='contextSearch')paintContexts()});document.addEventListener('change',e=>{if(['composeMerchant','composeTrigger','composeCustomer'].includes(e.target.id))syncComposer()});
async function generate(){const {mid,tid,cid}=S.compose||{};if(!mid||!tid)return toast('Select a merchant and trigger first','error');const steps=$$('#pipeline li');steps.forEach((x,i)=>{x.className=i<4?'done':'pending';x.querySelector('span').textContent=i<4?'✓':'○'});$('#validationSummary').textContent='Generating and validating against supplied context…';$('#generate').disabled=true;try{const result=await req('/v1/compose',{method:'POST',body:JSON.stringify({merchant_id:mid,trigger_id:tid,customer_id:cid||null})});S.compose.result=result;const m=result.message;$('#messagePreview').className='';$('#messagePreview').innerHTML=`<div class="bubble">${esc(m.body)}<span class="time">Vera · simulated preview</span></div>`;$('#messageMeta').innerHTML=`<span class="tag ${m.send_as==='vera'?'blue':'cyan'}">${esc(m.send_as)}</span><span class="tag">CTA · ${esc(m.cta)}</span><span class="tag">${esc(result.strategy)}</span><span class="tag gray">${esc(m.suppression_key)}</span>`;steps.forEach(x=>{x.className=result.validation.valid?'done':'pending';x.querySelector('span').textContent=result.validation.valid?'✓':'!' });$('#validationSummary').textContent=result.validation.valid?'Grounding and output checks passed.':'Validation warnings: '+result.validation.issues.join(', ');$('#copyMessage').disabled=false;$('#runConversation').disabled=!result.validation.valid;toast(result.validation.valid?'Message generated · validation passed':'Message generated with validation warnings',result.validation.valid?'ok':'error')}catch(err){$('#validationSummary').textContent='Generation failed: '+err.message;toast(err.message,'error')}finally{$('#generate').disabled=false}}
document.addEventListener('submit',async e=>{if(e.target.id!=='replyForm')return;e.preventDefault();const id=S.selectedConversation,msg=$('#replyText').value.trim();if(!id||!msg)return toast('Choose a conversation and enter a reply','error');try{const c=(S.data.conversations||[]).find(x=>x.conversation_id===id);const r=await req('/v1/reply',{method:'POST',body:JSON.stringify({conversation_id:id,merchant_id:c?.merchant_id,customer_id:c?.customer_id,from_role:c?.customer_id?'customer':'merchant',message:msg,received_at:new Date().toISOString(),turn_number:(c?.turn_number||1)+1})});await refreshData();render('conversations');toast(r.action==='end'?'Conversation ended':r.action==='wait'?`Vera will wait ${r.wait_seconds}s`:'Vera replied')}catch(err){toast(err.message,'error')}});
function $$(s){return [...document.querySelectorAll(s)]}
$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show')});
if(localStorage.getItem('vera-theme')==='light')document.body.classList.add('light');refreshData().then(()=>render('overview'));setInterval(async()=>{const ok=await refreshData();if(!ok)toast('Local data unavailable','error')},30000);
